'use client';

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Tabs, TabList, Tab, TabPanel } from '@mui/joy';
import InventoryView from '@/app/manager-dash/inventory/page';
import { fetchAllRestaurants, Restaurant } from '@/app/actions/restaurantActions';

// Temporary component until the real one is implemented
const PrepProcessView = ({ restaurantId }: { restaurantId: number | null }) => (
  <div>
    <h2>Prep Process View</h2>
    {restaurantId ? (
      <p>Viewing prep processes for restaurant ID: {restaurantId}</p>
    ) : (
      <p>Please select a restaurant to view prep processes.</p>
    )}
  </div>
);

// Temporary component until the real one is implemented
const PerformanceView = ({ restaurantId }: { restaurantId: number | null }) => (
  <div>
    <h2>Performance Metrics View</h2>
    {restaurantId ? (
      <p>Viewing performance metrics for restaurant ID: {restaurantId}</p>
    ) : (
      <p>Please select a restaurant to view performance metrics.</p>
    )}
  </div>
);

export default function RestaurantViewPage() {
  const [selectedRestaurant, setSelectedRestaurant] = useState<number | null>(null);
  
  // Fetch all restaurants the user has access to
  const { data: restaurants = [], isLoading } = useQuery<Restaurant[]>({
    queryKey: ['restaurants'],
    queryFn: fetchAllRestaurants,
  });

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-4">Restaurant Dashboard</h1>
      
      {/* Restaurant Selection */}
      <div className="mb-6">
        <h2 className="text-lg font-semibold mb-2">Select a Restaurant</h2>
        {isLoading ? (
          <div>Loading restaurants...</div>
        ) : (
          <div className="flex gap-2 flex-wrap">
            {restaurants.map((restaurant: Restaurant) => (
              <button
                key={restaurant.restaurantId}
                onClick={() => setSelectedRestaurant(restaurant.restaurantId)}
                className={`px-4 py-2 rounded ${
                  selectedRestaurant === restaurant.restaurantId
                    ? 'bg-blue-500 text-white'
                    : 'bg-gray-200'
                }`}
              >
                {restaurant.restaurantName}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Selected Restaurant Info */}
      {selectedRestaurant && (
        <div className="mb-6 p-4 bg-blue-50 rounded-lg">
          <h2 className="text-lg font-semibold">
            Currently Viewing: {restaurants.find(r => r.restaurantId === selectedRestaurant)?.restaurantName}
          </h2>
        </div>
      )}

      {/* View Tabs */}
      <Tabs defaultValue="inventory">
        <TabList>
          <Tab value="inventory">Inventory</Tab>
          <Tab value="prep">Preparation Processes</Tab>
          <Tab value="performance">Performance Metrics</Tab>
        </TabList>
        
        <TabPanel value="inventory">
          <InventoryView restaurantId={selectedRestaurant} />
        </TabPanel>
        
        <TabPanel value="prep">
          <PrepProcessView restaurantId={selectedRestaurant} />
        </TabPanel>
        
        <TabPanel value="performance">
          <PerformanceView restaurantId={selectedRestaurant} />
        </TabPanel>
      </Tabs>
    </div>
  );
} 